syntax:
struct StructName {
    type member1;
    type member2;
    ...
} __attribute__((init)) = { initializers };

// Or using constructor functions for complex initialization
void init_struct(struct StructName *s) {
    s->member1 = constant_expression;
    s->member2 = constant_expression;
    ...
}

code_example:
struct Data {
    int a;
    int b;
    bool flag;
} __attribute__((section(".init"))) = { 42, 0, true };

void initialize_data(struct Data *d) {
    d->a = 42;
    d->b = 0;
    d->flag = true;
}
